"use client"

import * as React from "react"

import { CodeViewerFallback } from "./code-viewer-chrome"
import { CodeViewerContent } from "./code-viewer-content"
import type { CodeViewerHandle, CodeViewerProps } from "./code-viewer-types"
import { PlainTextViewerFrame } from "./plain-text-viewer-frame"

export type {
  CodeDocumentSource,
  TextLineRange,
  CodeViewerHandle,
  CodeViewerProps,
} from "./code-viewer-types"

export const CodeViewer = React.forwardRef<CodeViewerHandle, CodeViewerProps>(
  function CodeViewer(props, ref) {
    return (
      <PlainTextViewerFrame
        props={props}
        forwardedRef={ref}
        clientFallbackPolicy="always"
        Fallback={CodeViewerFallback}
        Content={CodeViewerContent}
      />
    )
  }
)

"use client"

import * as React from "react"
import { RotateCcw } from "lucide-react"

import { type ViewerDownloadAction } from "@/lib/viewer-download"

import { Button } from "./button"
import { Skeleton } from "./skeleton"
import {
  TextCodeViewerFrame,
  TextCodeViewerToolbarFrame,
  TextCodeViewerZoomControls,
} from "./text-code-viewer-chrome"
import { ViewerDownloadControl } from "./viewer-download"

export function CodeViewerFrame({
  className,
  bare,
  children,
}: {
  className?: string
  bare?: boolean
  children: React.ReactNode
}) {
  return (
    <TextCodeViewerFrame
      bare={bare}
      bareClassName="h-full bg-muted/20"
      className={className}
      dataSlot="code-viewer"
      framedClassName="rounded-xl border bg-muted/30"
    >
      {children}
    </TextCodeViewerFrame>
  )
}

export function CodeViewerToolbar({
  lineCount,
  fontScale,
  downloadAction,
  onZoomOut,
  onZoomIn,
  onResetZoom,
}: {
  lineCount: number
  fontScale: number
  downloadAction: ViewerDownloadAction
  onZoomOut: () => void
  onZoomIn: () => void
  onResetZoom: () => void
}) {
  return (
    <TextCodeViewerToolbarFrame
      leading={`${lineCount} line${lineCount === 1 ? "" : "s"}`}
      trailing={
        <>
          <TextCodeViewerZoomControls
            fontScale={fontScale}
            onZoomOut={onZoomOut}
            onZoomIn={onZoomIn}
            onResetZoom={onResetZoom}
          />
          <div className="mx-1 h-4 w-px bg-border" />
          <ViewerDownloadControl actions={[downloadAction]} />
        </>
      }
    />
  )
}

export function CodeViewerFallback({
  className,
  toolbar = true,
  bare,
}: {
  className?: string
  toolbar?: boolean
  bare?: boolean
}) {
  return (
    <CodeViewerFrame className={className} bare={bare}>
      {toolbar ? (
        <TextCodeViewerToolbarFrame
          leading={<Skeleton className="inline-block h-3 w-16 align-middle" />}
          trailing={<TextCodeViewerZoomControls disabled fontScale={1} />}
        />
      ) : null}
      <div
        className="min-h-0 flex-1 space-y-2 overflow-hidden p-4"
        data-slot="code-body-skeleton"
      >
        {Array.from({ length: 12 }, (_, index) => (
          <Skeleton
            key={index}
            className="h-4"
            style={{ width: `${40 + ((index * 13) % 55)}%` }}
          />
        ))}
      </div>
    </CodeViewerFrame>
  )
}

export function CodeViewerErrorState({
  className,
  bare,
  message,
  isRetryable,
  downloadAction,
  onRetry,
}: {
  className?: string
  bare?: boolean
  message: string
  isRetryable: boolean
  downloadAction: ViewerDownloadAction
  onRetry: () => void
}) {
  return (
    <CodeViewerFrame className={className} bare={bare}>
      <div className="flex min-h-64 flex-1 flex-col items-center justify-center gap-3 p-6 text-center text-sm text-muted-foreground">
        <p>{message}</p>
        <div className="flex items-center gap-2">
          {isRetryable ? (
            <Button variant="outline" size="sm" onClick={onRetry}>
              <RotateCcw className="mr-1.5 size-4" />
              Retry
            </Button>
          ) : null}
          <ViewerDownloadControl
            actions={[downloadAction]}
            variant={message.includes("too large") ? "outline" : "ghost"}
            size="sm"
            className=""
            showLabel
          />
        </div>
      </div>
    </CodeViewerFrame>
  )
}

"use client"

import * as React from "react"
import { Maximize, Minus, Plus } from "lucide-react"

import { cn } from "@/lib/utils"

import { Button } from "./button"

export function TextCodeViewerFrame({
  bare,
  bareClassName,
  children,
  className,
  dataSlot,
  framedClassName,
}: {
  bare?: boolean
  bareClassName: string
  children: React.ReactNode
  className?: string
  dataSlot: string
  framedClassName: string
}) {
  return (
    <div
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? bareClassName : framedClassName,
        className
      )}
      data-slot={dataSlot}
    >
      {children}
    </div>
  )
}

export function TextCodeViewerToolbarFrame({
  leading,
  trailing,
}: {
  leading: React.ReactNode
  trailing: React.ReactNode
}) {
  return (
    <div className="flex h-10 flex-shrink-0 items-center gap-1 border-b bg-card px-2">
      <span className="px-1 text-xs text-muted-foreground tabular-nums">
        {leading}
      </span>
      <div className="ml-auto flex items-center gap-1">{trailing}</div>
    </div>
  )
}

export function TextCodeViewerZoomControls({
  fontScale,
  disabled = false,
  onZoomOut,
  onZoomIn,
  onResetZoom,
}: {
  fontScale: number
  disabled?: boolean
  onZoomOut?: () => void
  onZoomIn?: () => void
  onResetZoom?: () => void
}) {
  const disabledProps = disabled
    ? ({ disabled: true, tabIndex: -1, "aria-hidden": true } as const)
    : {}

  return (
    <>
      <TextCodeViewerIconButton
        label="Zoom out"
        onClick={disabled ? undefined : onZoomOut}
        {...disabledProps}
      >
        <Minus />
      </TextCodeViewerIconButton>
      <span className="w-12 text-center text-xs text-muted-foreground tabular-nums">
        {Math.round(fontScale * 100)}%
      </span>
      <TextCodeViewerIconButton
        label="Zoom in"
        onClick={disabled ? undefined : onZoomIn}
        {...disabledProps}
      >
        <Plus />
      </TextCodeViewerIconButton>
      <TextCodeViewerIconButton
        label="Reset zoom"
        onClick={disabled ? undefined : onResetZoom}
        {...disabledProps}
      >
        <Maximize />
      </TextCodeViewerIconButton>
    </>
  )
}

export function TextCodeViewerIconButton({
  label,
  children,
  ...props
}: React.ComponentProps<typeof Button> & { label: string }) {
  return (
    <Button
      variant="ghost"
      size="icon-sm"
      className="size-7"
      aria-label={label}
      title={label}
      {...props}
    >
      {children}
    </Button>
  )
}

"use client"

import * as React from "react"

import {
  isResourceError,
  isViewerFormatError,
  isViewerStateError,
  isViewerUnsupportedError,
  ViewerFormatError,
} from "@/lib/viewer-errors"
import {
  createViewerResource,
  type ViewerContentIdentity,
  type ViewerResource,
} from "@/lib/viewer-resource"
import type {
  BlobViewerSource,
  TextSource,
  UrlViewerSource,
} from "@/lib/viewer-source"

import {
  DEFAULT_MAX_BYTES,
  DEFAULT_MAX_LINES,
  type TextViewerBounds,
} from "./plain-text-resource"
import { useIsClient } from "./use-is-client"
import { ViewerErrorBoundary } from "./viewer-error"

type TextResourceSource = UrlViewerSource | BlobViewerSource | TextSource
type ClientFallbackPolicy = "always" | "non-inline-source"

export interface PlainTextViewerFrameProps<
  THandle,
  TProps extends PlainTextViewerFramePublicProps,
> {
  props: TProps
  forwardedRef: React.ForwardedRef<THandle>
  clientFallbackPolicy: ClientFallbackPolicy
  Fallback: React.ComponentType<PlainTextViewerFallbackProps>
  Content: React.ComponentType<
    TProps & {
      resource: ViewerResource
      retryVersion: number
      forwardedRef?: React.ForwardedRef<THandle>
    }
  >
}

export interface PlainTextViewerFramePublicProps extends TextViewerBounds {
  source: TextResourceSource
  className?: string
  toolbar?: boolean
  bare?: boolean
}

export interface PlainTextViewerFallbackProps {
  className?: string
  toolbar?: boolean
  bare?: boolean
}

export function PlainTextViewerFrame<
  THandle,
  TProps extends PlainTextViewerFramePublicProps,
>({
  props,
  forwardedRef,
  clientFallbackPolicy,
  Fallback,
  Content,
}: PlainTextViewerFrameProps<THandle, TProps>) {
  const [retryState, setRetryState] = React.useState({
    contentKey: "",
    version: 0,
  })
  const isClient = useIsClient()
  const { source } = props
  const resource = React.useMemo(() => createViewerResource(source), [source])
  const contentBaseKey = plainTextViewerContentBaseKey(resource.content, props)
  const retryVersion =
    retryState.contentKey === contentBaseKey ? retryState.version : 0
  const resetKey = plainTextViewerResetKey(resource, props, retryVersion)
  const contentResetKey = plainTextViewerContentResetKey(
    contentBaseKey,
    retryVersion
  )

  if (!isClient && shouldRenderClientFallback(clientFallbackPolicy, source)) {
    return (
      <Fallback
        className={props.className}
        toolbar={props.toolbar}
        bare={props.bare}
      />
    )
  }

  return (
    <ViewerErrorBoundary
      bare={props.bare}
      className={props.className}
      download={
        props.toolbar === false ? null : plainTextViewerDownloadAction(resource)
      }
      format="text"
      mapError={plainTextViewerBoundaryError}
      resetKey={resetKey}
      sourceKind={resource.sourceKind}
      onRetry={() =>
        setRetryState((state) => ({
          contentKey: contentBaseKey,
          version: state.contentKey === contentBaseKey ? state.version + 1 : 1,
        }))
      }
    >
      <React.Suspense
        key={contentResetKey}
        fallback={
          <Fallback
            className={props.className}
            toolbar={props.toolbar}
            bare={props.bare}
          />
        }
      >
        <Content
          {...props}
          forwardedRef={forwardedRef}
          retryVersion={retryVersion}
          resource={resource}
        />
      </React.Suspense>
    </ViewerErrorBoundary>
  )
}

function plainTextViewerDownloadAction(resource: ViewerResource) {
  return resource.originalDownload
}

function plainTextViewerBoundaryError(error: unknown) {
  if (
    isResourceError(error) ||
    isViewerFormatError(error) ||
    isViewerStateError(error) ||
    isViewerUnsupportedError(error)
  ) {
    return error
  }

  return new ViewerFormatError({
    format: "text",
    kind: "render_failed",
    message: "Failed to render text.",
    cause: error,
  })
}

function plainTextViewerResetKey(
  resource: ViewerResource,
  props: Pick<PlainTextViewerFramePublicProps, "maxBytes" | "maxLines">,
  retryVersion: number
): string {
  const [maxBytesKey, maxLinesKey] = plainTextViewerBoundsResetKey(props)
  return [resource.keys.resource, retryVersion, maxBytesKey, maxLinesKey].join(
    "\u0000"
  )
}

function plainTextViewerContentResetKey(
  contentBaseKey: string,
  retryVersion: number
): string {
  return [contentBaseKey, retryVersion].join("\u0000")
}

function plainTextViewerContentBaseKey(
  content: ViewerContentIdentity,
  props: Pick<PlainTextViewerFramePublicProps, "maxBytes" | "maxLines">
): string {
  const [maxBytesKey, maxLinesKey] = plainTextViewerBoundsResetKey(props)
  return [content.key, maxBytesKey, maxLinesKey].join("\u0000")
}

function plainTextViewerBoundsResetKey(
  props: Pick<PlainTextViewerFramePublicProps, "maxBytes" | "maxLines">
) {
  return [
    plainTextViewerBoundResetKeyPart(props.maxBytes, DEFAULT_MAX_BYTES),
    plainTextViewerBoundResetKeyPart(props.maxLines, DEFAULT_MAX_LINES),
  ] as const
}

function plainTextViewerBoundResetKeyPart(
  value: number | undefined,
  defaultValue: number
) {
  return String(value === undefined ? defaultValue : value)
}

function shouldRenderClientFallback(
  policy: ClientFallbackPolicy,
  source: TextResourceSource
) {
  return policy === "always" || source.kind !== "text"
}

"use client"

import * as React from "react"

import type { ViewerResource } from "@/lib/viewer-resource"

import { CodeViewerFrame, CodeViewerToolbar } from "./code-viewer-chrome"
import { scrollLineRangeMetricsIntoView } from "./code-viewer-layout"
import { useCodeProjectionScheduler } from "./code-viewer-projection-scheduler"
import { createCodeProjector } from "./code-viewer-projector"
import {
  clampCodeViewerScale,
  CODE_VIEWER_BASE_LINE_PX,
  CODE_VIEWER_BLOCK_PADDING,
} from "./code-viewer-scale"
import { createCodeSyntax } from "./code-viewer-syntax"
import { useCodeViewerSyntaxStyle } from "./code-viewer-syntax-style"
import type { CodeViewerHandle, CodeViewerProps } from "./code-viewer-types"
import { CodeViewerViewport } from "./code-viewer-viewport"
import { normalizeTextLineRange } from "./line-ranges"
import {
  readTextResource,
  resolvedTextViewerBounds,
  splitTextLines,
} from "./plain-text-resource"

export function CodeViewerContent({
  resource,
  className,
  toolbar = true,
  highlight,
  bare = false,
  maxBytes,
  maxLines,
  retryVersion,
  forwardedRef,
}: CodeViewerProps & {
  resource: ViewerResource
  retryVersion: number
  forwardedRef?: React.ForwardedRef<CodeViewerHandle>
}) {
  const bounds = resolvedTextViewerBounds({ maxBytes, maxLines })
  const text = readTextResource({
    content: resource.content,
    retryVersion,
    bounds,
  })
  const textLines = React.useMemo(() => splitTextLines(text), [text])
  const syntax = React.useMemo(() => createCodeSyntax(resource), [resource])
  const highlightStart = highlight?.start
  const highlightEnd = highlight?.end
  const highlightRange = React.useMemo(
    () =>
      normalizeTextLineRange(
        highlightStart == null || highlightEnd == null
          ? null
          : { start: highlightStart, end: highlightEnd },
        textLines.length
      ),
    [highlightStart, highlightEnd, textLines.length]
  )
  const downloadAction = React.useMemo(
    () => resource.originalDownload,
    [resource]
  )

  const [fontScale, setFontScale] = React.useState(1)
  const viewportRef = React.useRef<HTMLDivElement | null>(null)
  const rowHostRef = React.useRef<HTMLPreElement | null>(null)
  const projector = React.useMemo(() => createCodeProjector(), [])
  const lineHeight = CODE_VIEWER_BASE_LINE_PX * fontScale
  const contentIdentity = React.useMemo(
    () =>
      codeContentIdentity({
        contentKey: resource.content.key,
        maxBytes: bounds.maxBytes,
        maxLines: bounds.maxLines,
        retryVersion,
      }),
    [bounds.maxBytes, bounds.maxLines, resource.content.key, retryVersion]
  )
  const gutterWidth = `calc(${String(textLines.length).length + 1}ch + 1.25rem)`
  const layoutIdentity = codeLayoutIdentity({ gutterWidth, lineHeight })

  useCodeViewerSyntaxStyle()

  const zoom = (factor: number) =>
    setFontScale((scale) => clampCodeViewerScale(scale * factor))

  React.useImperativeHandle(
    forwardedRef ?? null,
    () => ({
      scrollToLineRange: (range, options) => {
        scrollLineRangeMetricsIntoView({
          viewportElement: viewportRef.current,
          range: normalizeTextLineRange(range, textLines.length),
          lineHeight,
          paddingStart: CODE_VIEWER_BLOCK_PADDING,
          options,
        })
      },
      getViewportElement: () => viewportRef.current,
    }),
    [lineHeight, textLines.length]
  )

  React.useEffect(() => {
    scrollLineRangeMetricsIntoView({
      viewportElement: viewportRef.current,
      range: highlightRange,
      lineHeight,
      paddingStart: CODE_VIEWER_BLOCK_PADDING,
    })
  }, [highlightRange, lineHeight])

  const project = React.useCallback(() => {
    const rowHost = rowHostRef.current
    const viewport = viewportRef.current
    if (!rowHost || !viewport) return

    projector.project({
      contentIdentity,
      gutterWidth,
      highlightRange,
      layoutIdentity,
      lineHeight,
      rowHost,
      syntax,
      syntaxIdentity: syntax.identity,
      textLines,
      viewport,
    })
  }, [
    contentIdentity,
    gutterWidth,
    highlightRange,
    layoutIdentity,
    lineHeight,
    projector,
    syntax,
    textLines,
  ])

  useCodeProjectionScheduler({
    project,
    viewportRef,
  })

  React.useEffect(() => () => projector.destroy(), [projector])

  return (
    <CodeViewerFrame className={className} bare={bare}>
      {toolbar ? (
        <CodeViewerToolbar
          lineCount={textLines.length}
          fontScale={fontScale}
          downloadAction={downloadAction}
          onZoomOut={() => zoom(1 / 1.2)}
          onZoomIn={() => zoom(1.2)}
          onResetZoom={() => setFontScale(1)}
        />
      ) : null}
      <CodeViewerViewport
        contentIdentity={contentIdentity}
        fontScale={fontScale}
        lineCount={textLines.length}
        lineHeight={lineHeight}
        rowHostRef={rowHostRef}
        viewportRef={viewportRef}
      />
    </CodeViewerFrame>
  )
}

function codeContentIdentity({
  contentKey,
  maxBytes,
  maxLines,
  retryVersion,
}: {
  contentKey: string
  maxBytes: number
  maxLines: number
  retryVersion: number
}) {
  return [contentKey, retryVersion, maxBytes, maxLines].join("\u0000")
}

function codeLayoutIdentity({
  gutterWidth,
  lineHeight,
}: {
  gutterWidth: string
  lineHeight: number
}) {
  return [lineHeight, gutterWidth].join("\u0000")
}

import {
  CODE_VIEWER_BLOCK_PADDING,
  CODE_VIEWER_INITIAL_VIEWPORT_HEIGHT,
  CODE_VIEWER_OVERSCAN,
} from "./code-viewer-scale"
import type { CodeSyntax, CodeTokenLeaf } from "./code-viewer-syntax"
import {
  getCodeVirtualLines,
  getCodeVirtualTotalSize,
  type CodeVirtualLine,
} from "./code-viewer-virtualization"
import { isLineInRange, type NormalizedTextLineRange } from "./line-ranges"

export type CodeProjectionIdentity = {
  contentIdentity: string
  layoutIdentity: string
  syntaxIdentity: string
}

export type CodeProjectionInput = CodeProjectionIdentity & {
  rowHost: HTMLPreElement
  viewport: HTMLDivElement
  textLines: readonly string[]
  lineHeight: number
  gutterWidth: string
  highlightRange: NormalizedTextLineRange | null
  syntax: CodeSyntax
}

export type CodeProjector = {
  project(input: CodeProjectionInput): void
  destroy(): void
}

type CodeRowCache = {
  contentIdentity: string
  contentSpan: HTMLSpanElement
  gutterSpan: HTMLSpanElement
  layoutIdentity: string
  row: HTMLDivElement
}

type VisibleRange = {
  end: number
  start: number
}

const CODE_TOKEN_CLASS: Record<string, string> = {
  boolean: "cv-token-keyword",
  keyword: "cv-token-keyword",
  null: "cv-token-keyword",
  number: "cv-token-number",
  operator: "cv-token-punctuation",
  property: "cv-token-property",
  punctuation: "cv-token-punctuation",
  string: "cv-token-string",
}

export function createCodeProjector(): CodeProjector {
  let identity: CodeProjectionIdentity | null = null
  let rowHost: HTMLPreElement | null = null
  let rows: Array<CodeRowCache | undefined> = []
  let visibleRange: VisibleRange | null = null

  return {
    project(input) {
      if (rowHost !== input.rowHost) {
        rowHost = input.rowHost
        clearRows()
      }

      const nextIdentity = codeProjectionIdentity(input)
      if (
        !identity ||
        identity.contentIdentity !== nextIdentity.contentIdentity
      ) {
        identity = nextIdentity
        clearRows()
      } else {
        identity = nextIdentity
      }

      setStyleValue(
        input.rowHost.style,
        "height",
        `${getCodeVirtualTotalSize({
          lineCount: input.textLines.length,
          lineHeight: input.lineHeight,
        })}px`
      )

      const visibleLines = getCodeVirtualLines({
        lineCount: input.textLines.length,
        lineHeight: input.lineHeight,
        overscan: CODE_VIEWER_OVERSCAN,
        paddingStart: CODE_VIEWER_BLOCK_PADDING,
        scrollTop: input.viewport.scrollTop,
        viewportHeight:
          input.viewport.clientHeight || CODE_VIEWER_INITIAL_VIEWPORT_HEIGHT,
      })
      const nextVisibleRange = codeVisibleRange(visibleLines)

      removeRowsOutsideVisibleRange(nextVisibleRange)

      syncVisibleRowOrder({
        input,
        visibleLines,
      })
      visibleRange = nextVisibleRange
    },
    destroy() {
      clearRows()
      rowHost = null
      identity = null
    },
  }

  function syncVisibleRowOrder({
    input,
    visibleLines,
  }: {
    input: CodeProjectionInput
    visibleLines: readonly CodeVirtualLine[]
  }) {
    let cursor = input.rowHost.firstChild

    for (const visibleLine of visibleLines) {
      const row = prepareCodeRow({
        input,
        visibleLine,
      })
      if (row !== cursor) {
        input.rowHost.insertBefore(row, cursor)
      }
      cursor = row.nextSibling
    }

    while (cursor) {
      const nextCursor = cursor.nextSibling
      cursor.parentNode?.removeChild(cursor)
      cursor = nextCursor
    }
  }

  function clearRows() {
    rowHost?.replaceChildren()
    rows = []
    visibleRange = null
  }

  function removeRowsOutsideVisibleRange(nextVisibleRange: VisibleRange) {
    if (!visibleRange) return

    removeCodeRowRange(visibleRange.start, nextVisibleRange.start)
    removeCodeRowRange(nextVisibleRange.end, visibleRange.end)
  }

  function removeCodeRowRange(start: number, end: number) {
    for (
      let index = Math.max(0, start);
      index < Math.max(start, end);
      index++
    ) {
      const row = rows[index]
      if (!row) continue
      row.row.remove()
      rows[index] = undefined
    }
  }

  function prepareCodeRow({
    input,
    visibleLine,
  }: {
    input: CodeProjectionInput
    visibleLine: CodeVirtualLine
  }): HTMLDivElement {
    const lineNumber = visibleLine.index + 1
    const text = input.textLines[visibleLine.index] ?? ""
    const isHighlighted = isLineInRange(lineNumber, input.highlightRange)
    const layoutIdentity = [
      lineNumber,
      input.layoutIdentity,
      isHighlighted ? "highlighted" : "",
    ].join("\u0000")
    const contentIdentity = [text, input.syntaxIdentity].join("\u0000")

    let row = rows[visibleLine.index]
    if (!row) {
      row = createCodeRow()
      rows[visibleLine.index] = row
    }

    setStyleValue(row.row.style, "height", `${visibleLine.size}px`)
    setStyleValue(
      row.row.style,
      "transform",
      `translateY(${visibleLine.start}px)`
    )

    if (row.layoutIdentity !== layoutIdentity) {
      row.layoutIdentity = layoutIdentity
      patchCodeRowLayout({
        gutterWidth: input.gutterWidth,
        isHighlighted,
        lineNumber,
        row,
      })
    }

    if (row.contentIdentity !== contentIdentity) {
      row.contentIdentity = contentIdentity
      patchCodeRowContent({
        row,
        syntax: input.syntax,
        text,
      })
    }

    return row.row
  }
}

function codeProjectionIdentity({
  contentIdentity,
  layoutIdentity,
  syntaxIdentity,
}: CodeProjectionIdentity): CodeProjectionIdentity {
  return {
    contentIdentity,
    layoutIdentity,
    syntaxIdentity,
  }
}

function codeVisibleRange(
  visibleLines: readonly CodeVirtualLine[]
): VisibleRange {
  const start = visibleLines[0]?.index ?? 0
  const end = visibleLines.length
    ? visibleLines[visibleLines.length - 1]!.index + 1
    : start
  return { end, start }
}

function createCodeRow(): CodeRowCache {
  const row = document.createElement("div")
  const gutterSpan = document.createElement("span")
  const contentSpan = document.createElement("span")

  row.className = codeRowClassName(false)
  row.style.position = "absolute"
  row.style.top = "0"
  row.style.left = "0"

  gutterSpan.className =
    "sticky left-0 z-10 flex-shrink-0 border-r bg-muted/30 px-2 pr-3 text-right text-muted-foreground/60 select-none"
  gutterSpan.dataset.codeGutter = ""
  gutterSpan.setAttribute("aria-hidden", "true")
  contentSpan.className = "whitespace-pre px-2"

  row.append(gutterSpan, contentSpan)

  return {
    contentIdentity: "",
    contentSpan,
    gutterSpan,
    layoutIdentity: "",
    row,
  }
}

function patchCodeRowLayout({
  gutterWidth,
  isHighlighted,
  lineNumber,
  row,
}: {
  gutterWidth: string
  isHighlighted: boolean
  lineNumber: number
  row: CodeRowCache
}) {
  row.row.dataset.lineNumber = String(lineNumber)
  row.row.className = codeRowClassName(isHighlighted)
  setStyleValue(row.gutterSpan.style, "width", gutterWidth)
  setTextContent(row.gutterSpan, String(lineNumber))
}

function patchCodeRowContent({
  row,
  syntax,
  text,
}: {
  row: CodeRowCache
  syntax: CodeSyntax
  text: string
}) {
  patchCodeContent(row.contentSpan, syntax.getLineTokens(text), text)
}

function patchCodeContent(
  contentSpan: HTMLSpanElement,
  leaves: readonly CodeTokenLeaf[] | null,
  text: string
) {
  if (text === "") {
    contentSpan.replaceChildren()
    contentSpan.textContent = " "
    return
  }
  if (!leaves) {
    setTextContent(contentSpan, text)
    return
  }

  contentSpan.replaceChildren()
  const fragment = document.createDocumentFragment()
  for (const leaf of leaves) {
    const className = CODE_TOKEN_CLASS[leaf.kind]
    if (!className) {
      fragment.append(document.createTextNode(leaf.text))
      continue
    }
    const span = document.createElement("span")
    span.className = className
    span.textContent = leaf.text
    fragment.append(span)
  }
  contentSpan.append(fragment)
}

function codeRowClassName(isHighlighted: boolean) {
  return [
    "absolute top-0 left-0 flex min-w-full",
    isHighlighted ? "bg-primary/12 ring-1 ring-primary/30 ring-inset" : "",
  ]
    .filter(Boolean)
    .join(" ")
}

function setStyleValue(
  style: CSSStyleDeclaration,
  propertyName: string,
  value: string
) {
  if (style.getPropertyValue(propertyName) !== value) {
    style.setProperty(propertyName, value)
  }
}

function setTextContent(element: HTMLElement, text: string) {
  if (element.textContent !== text) {
    element.textContent = text
  }
}

"use client"

import * as React from "react"

export function useCodeProjectionScheduler({
  project,
  viewportRef,
}: {
  project: () => void
  viewportRef: React.RefObject<HTMLDivElement | null>
}) {
  const scheduledProjectionRef = React.useRef(0)

  const scheduleProjection = React.useCallback(() => {
    if (scheduledProjectionRef.current) return
    scheduledProjectionRef.current = requestAnimationFrame(() => {
      scheduledProjectionRef.current = 0
      project()
    })
  }, [project])

  React.useLayoutEffect(() => {
    project()
    return () => {
      if (!scheduledProjectionRef.current) return
      cancelAnimationFrame(scheduledProjectionRef.current)
      scheduledProjectionRef.current = 0
    }
  }, [project])

  React.useLayoutEffect(() => {
    const viewport = viewportRef.current
    if (!viewport) return

    viewport.addEventListener("scroll", scheduleProjection, { passive: true })
    const observer =
      typeof ResizeObserver === "undefined"
        ? null
        : new ResizeObserver(scheduleProjection)
    observer?.observe(viewport)

    return () => {
      viewport.removeEventListener("scroll", scheduleProjection)
      observer?.disconnect()
      if (!scheduledProjectionRef.current) return
      cancelAnimationFrame(scheduledProjectionRef.current)
      scheduledProjectionRef.current = 0
    }
  }, [scheduleProjection, viewportRef])
}

import type { NormalizedTextLineRange } from "./line-ranges"

export const LINE_SCROLL_HEADROOM = 64

export interface LineRangeRects {
  startTop: number
  endBottom: number
  viewportTop: number
  viewportScrollTop: number
  viewportHeight: number
}

export interface LineRangeMetrics {
  startLine: number
  endLine: number
  lineHeight: number
  viewportHeight: number
  paddingStart?: number
}

export function findLineElement(
  viewportElement: HTMLElement,
  lineNumber: number
): HTMLElement | null {
  if (!Number.isInteger(lineNumber) || lineNumber < 1) return null
  return viewportElement.querySelector<HTMLElement>(
    `[data-line-number="${lineNumber}"]`
  )
}

export function scrollTopForLineRange({
  startTop,
  endBottom,
  viewportTop,
  viewportScrollTop,
  viewportHeight,
}: LineRangeRects) {
  const rangeTop = startTop - viewportTop + viewportScrollTop
  const rangeBottom = endBottom - viewportTop + viewportScrollTop
  const rangeHeight = rangeBottom - rangeTop
  const targetTop =
    rangeHeight <= viewportHeight
      ? rangeTop - (viewportHeight - rangeHeight) / 2
      : rangeTop - LINE_SCROLL_HEADROOM

  return Math.max(0, targetTop)
}

export function scrollTopForLineRangeMetrics({
  startLine,
  endLine,
  lineHeight,
  viewportHeight,
  paddingStart = 0,
}: LineRangeMetrics) {
  const rangeTop = paddingStart + (startLine - 1) * lineHeight
  const rangeBottom = paddingStart + endLine * lineHeight
  const rangeHeight = rangeBottom - rangeTop
  const targetTop =
    rangeHeight <= viewportHeight
      ? rangeTop - (viewportHeight - rangeHeight) / 2
      : rangeTop - LINE_SCROLL_HEADROOM

  return Math.max(0, targetTop)
}

export function scrollLineRangeIntoView({
  viewportElement,
  range,
  options,
}: {
  viewportElement: HTMLDivElement | null
  range: NormalizedTextLineRange | null
  options?: ScrollToOptions
}) {
  if (!viewportElement || !range) return

  const startLineElement = findLineElement(viewportElement, range.start)
  const endLineElement = findLineElement(viewportElement, range.end)
  if (!startLineElement || !endLineElement) return

  const startLineRect = startLineElement.getBoundingClientRect()
  const endLineRect = endLineElement.getBoundingClientRect()
  const viewportRect = viewportElement.getBoundingClientRect()

  viewportElement.scrollTo({
    top: scrollTopForLineRange({
      startTop: startLineRect.top,
      endBottom: endLineRect.bottom,
      viewportTop: viewportRect.top,
      viewportScrollTop: viewportElement.scrollTop,
      viewportHeight: viewportElement.clientHeight,
    }),
    behavior: "smooth",
    ...options,
  })
}

export function scrollLineRangeMetricsIntoView({
  viewportElement,
  range,
  lineHeight,
  paddingStart,
  options,
}: {
  viewportElement: HTMLDivElement | null
  range: NormalizedTextLineRange | null
  lineHeight: number
  paddingStart?: number
  options?: ScrollToOptions
}) {
  if (!viewportElement || !range) return
  if (typeof viewportElement.scrollTo !== "function") return

  viewportElement.scrollTo({
    top: scrollTopForLineRangeMetrics({
      startLine: range.start,
      endLine: range.end,
      lineHeight,
      paddingStart,
      viewportHeight: viewportElement.clientHeight,
    }),
    behavior: "smooth",
    ...options,
  })
}

