import * as React from "react"
import { Download } from "lucide-react"

import { cn } from "@/lib/utils"
import {
  ViewerDownloadError,
  type ViewerDownloadAction,
  type ViewerDownloadPayload,
} from "@/lib/viewer-download"

import { Button, buttonVariants } from "./button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "./dropdown-menu"

export interface TriggerViewerDownloadOptions {
  signal?: AbortSignal
}

export async function triggerViewerDownload(
  action: ViewerDownloadAction,
  options?: TriggerViewerDownloadOptions
): Promise<void> {
  if (action.isDisabled) {
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "disabled",
      message: "This download is disabled.",
    })
  }

  let payload: ViewerDownloadPayload
  try {
    payload = await action.getPayload(options)
  } catch (error) {
    if (isAbortError(error)) {
      throw new ViewerDownloadError({
        actionId: action.id,
        kind: "aborted",
        message: "Download was cancelled.",
        cause: error,
      })
    }
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "payload_failed",
      message: "Could not prepare this download.",
      cause: error,
    })
  }

  if (payload.kind === "none") return
  if (payload.kind === "href") {
    try {
      clickDownload(payload.href, action.fileName)
    } catch (error) {
      throw new ViewerDownloadError({
        actionId: action.id,
        kind: "unsupported",
        message: "Could not start this download.",
        cause: error,
      })
    }
    return
  }

  try {
    const blob =
      payload.kind === "blob"
        ? payload.blob
        : new Blob([payload.text], {
            type: payload.mimeType ?? "text/plain;charset=utf-8",
          })
    const url = URL.createObjectURL(blob)
    try {
      clickDownload(url, action.fileName)
    } finally {
      URL.revokeObjectURL(url)
    }
  } catch (error) {
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "unsupported",
      message: "Could not start this download.",
      cause: error,
    })
  }
}

export type ViewerDownloadErrorHandler = (
  error: ViewerDownloadError,
  action: ViewerDownloadAction
) => void

export interface ViewerDownloadTrigger {
  pendingActionId: string | null
  triggerDownload: (action: ViewerDownloadAction) => void
}

export interface ViewerDownloadTriggerOptions {
  /** Reports non-aborted action failures; visible failure UI belongs to consumers. */
  onError?: ViewerDownloadErrorHandler
  resetKey?: unknown
}

export interface ViewerDownloadControlProps {
  actions: Array<ViewerDownloadAction | null | undefined>
  variant?: React.ComponentProps<typeof Button>["variant"]
  size?: React.ComponentProps<typeof Button>["size"]
  className?: string
  showLabel?: boolean
  /** Reports non-aborted action failures; visible failure UI belongs to consumers. */
  onError?: ViewerDownloadErrorHandler
}

export interface ViewerDownloadButtonProps
  extends Omit<ViewerDownloadControlProps, "actions"> {
  action: ViewerDownloadAction | null
}

export interface ViewerDownloadMenuProps
  extends Omit<ViewerDownloadControlProps, "actions"> {
  actions: ViewerDownloadAction[]
}

export function useViewerDownloadHref(
  action: ViewerDownloadAction | null
): string | null {
  const shouldCreateHref = action?.origin !== "derived"
  const payload = shouldCreateHref ? getSynchronousPayload(action) : null

  return shouldCreateHref && payload?.kind === "href" ? payload.href : null
}

export function useViewerDownloadTrigger({
  onError,
  resetKey = "",
}: ViewerDownloadTriggerOptions = {}): ViewerDownloadTrigger {
  const [pendingActionId, setPendingActionId] = React.useState<string | null>(
    null
  )
  const abortControllerRef = React.useRef<AbortController | null>(null)

  React.useEffect(() => {
    return () => {
      abortControllerRef.current?.abort()
      abortControllerRef.current = null
    }
  }, [resetKey])

  const triggerDownload = React.useCallback(
    (action: ViewerDownloadAction) => {
      abortControllerRef.current?.abort()
      const abortController = new AbortController()
      abortControllerRef.current = abortController
      setPendingActionId(action.id)
      void triggerViewerDownload(action, { signal: abortController.signal })
        .catch((error) => {
          reportDownloadError(error, action, onError)
        })
        .finally(() => {
          if (abortControllerRef.current === abortController) {
            abortControllerRef.current = null
            setPendingActionId(null)
          }
        })
    },
    [onError]
  )

  return { pendingActionId, triggerDownload }
}

export function ViewerDownloadControl({
  actions,
  variant = "ghost",
  size = "icon-sm",
  className = "size-7",
  showLabel = false,
  onError,
}: ViewerDownloadControlProps) {
  const enabledActions = actions.filter(
    (action): action is ViewerDownloadAction => Boolean(action)
  )

  if (enabledActions.length <= 1) {
    return (
      <ViewerDownloadButton
        action={enabledActions[0] ?? null}
        variant={variant}
        size={size}
        className={className}
        showLabel={showLabel}
        onError={onError}
      />
    )
  }

  return (
    <ViewerDownloadMenu
      actions={enabledActions}
      variant={variant}
      size={size}
      className={className}
      showLabel={showLabel}
      onError={onError}
    />
  )
}

export function ViewerDownloadButton({
  action,
  variant = "ghost",
  size = "icon-sm",
  className = "size-7",
  showLabel = false,
  onError,
}: ViewerDownloadButtonProps) {
  const href = useViewerDownloadHref(action)
  const label = action?.label ?? "Download"
  const disabled = !action || action.isDisabled
  const hasDownloadHref = Boolean(href)
  const { pendingActionId, triggerDownload } = useViewerDownloadTrigger({
    onError,
    resetKey: action,
  })
  const isPending = Boolean(action && pendingActionId === action.id)

  const handleClick = React.useCallback(() => {
    if (!action || hasDownloadHref) return
    triggerDownload(action)
  }, [action, hasDownloadHref, triggerDownload])

  if (href) {
    return (
      <a
        href={href}
        download={action?.fileName}
        className={cn(buttonVariants({ variant, size }), className)}
        aria-label={label}
        title={label}
        data-slot="button"
      >
        <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
        {showLabel ? label : null}
      </a>
    )
  }

  return (
    <Button
      variant={variant}
      size={size}
      className={className}
      aria-label={label}
      title={label}
      disabled={disabled}
      loading={isPending}
      onClick={handleClick}
    >
      <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
      {showLabel ? label : null}
    </Button>
  )
}

export function ViewerDownloadMenu({
  actions,
  variant = "ghost",
  size = "icon-sm",
  className = "size-7",
  showLabel = false,
  onError,
}: ViewerDownloadMenuProps) {
  const actionSetKey = actions.map((action) => action.id).join("\u0000")
  const label = "Download"
  const { pendingActionId, triggerDownload } = useViewerDownloadTrigger({
    onError,
    resetKey: actionSetKey,
  })

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            variant={variant}
            size={size}
            className={className}
            aria-label={label}
            title={label}
            loading={pendingActionId != null}
          >
            <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
            {showLabel ? label : null}
          </Button>
        }
      />
      <DropdownMenuContent align="end">
        {actions.map((action) => (
          <DropdownMenuItem
            key={action.id}
            disabled={action.isDisabled || pendingActionId != null}
            onClick={() => triggerDownload(action)}
          >
            <Download />
            <span>{action.label}</span>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

function clickDownload(href: string, fileName: string) {
  const anchor = document.createElement("a")
  anchor.href = href
  anchor.download = fileName
  anchor.rel = "noreferrer"
  document.body.appendChild(anchor)
  anchor.click()
  anchor.remove()
}

function getSynchronousPayload(
  action: ViewerDownloadAction | null
): ViewerDownloadPayload | null {
  if (!action || action.isDisabled) return null
  const payload = action.getPayload()
  return payload instanceof Promise ? null : payload
}

function reportDownloadError(
  error: unknown,
  action: ViewerDownloadAction,
  onError: ViewerDownloadErrorHandler | undefined
) {
  if (!(error instanceof ViewerDownloadError)) return
  if (error.kind === "aborted") return
  onError?.(error, action)
}

function isAbortError(error: unknown) {
  return error instanceof DOMException && error.name === "AbortError"
}

"use client"

import * as React from "react"
import { RotateCcw } from "lucide-react"

import { cn } from "@/lib/utils"
import type { ViewerDownloadAction } from "@/lib/viewer-download"
import {
  toViewerErrorInfo,
  type ViewerErrorContext,
  type ViewerFormat,
} from "@/lib/viewer-errors"

import { Button } from "./button"
import { ViewerDownloadButton } from "./viewer-download"

export interface ViewerErrorStateProps extends ViewerErrorContext {
  error: unknown
  download?: ViewerDownloadAction | null
  className?: string
  bare?: boolean
  variant?: "card" | "document" | "inline"
  onRetry?: () => void
}

export function ViewerErrorState({
  error,
  format,
  sourceKind,
  canDownload,
  retry,
  download,
  className,
  bare = false,
  variant = "card",
  onRetry,
}: ViewerErrorStateProps) {
  const info = toViewerErrorInfo(error, {
    format,
    sourceKind,
    canDownload: canDownload ?? Boolean(download && !download.isDisabled),
    retry,
  })
  const showRetry = info.isRetryable && onRetry
  const showDownload =
    info.isDownloadUseful && download != null && !download.isDisabled

  return (
    <div
      className={cn(errorStateClassName({ bare, variant }), className)}
      data-error-domain={info.domain}
      data-error-format={info.format}
      data-error-kind={info.kind}
      data-error-message={info.message}
      data-slot="viewer-error"
      role="alert"
    >
      <p>{info.userMessage}</p>
      {showRetry || showDownload ? (
        <div className="flex items-center gap-2">
          {showRetry ? (
            <Button variant="outline" size="sm" onClick={onRetry}>
              <RotateCcw className="mr-1.5 size-4" />
              Retry
            </Button>
          ) : null}
          {showDownload ? (
            <ViewerDownloadButton
              action={download}
              variant={showRetry ? "ghost" : "outline"}
              size="sm"
              className=""
              showLabel
            />
          ) : null}
        </div>
      ) : null}
    </div>
  )
}

export interface ViewerErrorBoundaryProps extends ViewerErrorContext {
  children: React.ReactNode
  resetKey?: unknown
  download?: ViewerDownloadAction | null
  className?: string
  bare?: boolean
  variant?: "card" | "document" | "inline"
  mapError?: (error: unknown) => unknown
  onRetry?: (error: unknown) => void
  onCaughtError?: (error: unknown, errorInfo: React.ErrorInfo) => void
}

export class ViewerErrorBoundary extends React.Component<
  ViewerErrorBoundaryProps,
  { error: unknown | null; retryKey: number }
> {
  state: Readonly<{ error: unknown | null; retryKey: number }> = {
    error: null,
    retryKey: 0,
  }

  componentDidUpdate(previousProps: ViewerErrorBoundaryProps) {
    if (
      previousProps.resetKey !== this.props.resetKey &&
      this.state.error != null
    ) {
      this.setState({ error: null })
    }
  }

  static getDerivedStateFromError(error: unknown) {
    return { error }
  }

  componentDidCatch(error: unknown, errorInfo: React.ErrorInfo) {
    this.props.onCaughtError?.(error, errorInfo)
  }

  render() {
    if (this.state.error != null) {
      const error = this.props.mapError
        ? this.props.mapError(this.state.error)
        : this.state.error

      return (
        <ViewerErrorState
          error={error}
          format={this.props.format}
          sourceKind={this.props.sourceKind}
          canDownload={this.props.canDownload}
          retry={this.props.retry}
          download={this.props.download}
          className={this.props.className}
          bare={this.props.bare}
          variant={this.props.variant}
          onRetry={() => {
            this.setState((state) => ({
              error: null,
              retryKey: state.retryKey + 1,
            }))
            this.props.onRetry?.(this.state.error)
          }}
        />
      )
    }

    return (
      <React.Fragment key={this.state.retryKey}>
        {this.props.children}
      </React.Fragment>
    )
  }
}

function errorStateClassName({
  bare,
  variant,
}: {
  bare: boolean
  variant: "card" | "document" | "inline"
}) {
  if (variant === "inline") {
    return "flex h-24 flex-col items-center justify-center gap-3 px-3 text-center text-xs text-muted-foreground"
  }
  return cn(
    "flex min-h-64 flex-col items-center justify-center gap-3 p-6 text-center text-sm text-muted-foreground",
    bare ? "bg-muted/20" : "rounded-xl border bg-muted/30",
    variant === "document" && "min-h-full"
  )
}

export type { ViewerFormat }

export interface TextLineRange {
  start: number
  end: number
}

export interface NormalizedTextLineRange extends TextLineRange {
  readonly normalized: true
}

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value))

export function normalizeTextLineRange(
  range: TextLineRange | null | undefined,
  lineCount: number
): NormalizedTextLineRange | null {
  if (
    !range ||
    !Number.isFinite(range.start) ||
    !Number.isFinite(range.end) ||
    !Number.isFinite(lineCount) ||
    lineCount <= 0
  ) {
    return null
  }

  const maxLine = Math.floor(lineCount)
  const rawStart = Math.trunc(range.start)
  const rawEnd = Math.trunc(range.end)
  const start = Math.min(rawStart, rawEnd)
  const end = Math.max(rawStart, rawEnd)

  if (end < 1 || start > maxLine) return null

  return {
    start: clamp(start, 1, maxLine),
    end: clamp(end, 1, maxLine),
    normalized: true,
  }
}

export function isLineInRange(
  lineNumber: number,
  range: NormalizedTextLineRange | null
) {
  return range != null && lineNumber >= range.start && lineNumber <= range.end
}

import {
  isResourceError,
  isViewerFormatError,
  ViewerFormatError,
  type ViewerFormatErrorMapperOptions,
} from "@/lib/viewer-errors"
import type {
  ViewerContentIdentity,
  ViewerContentPayload,
  ViewerContentText,
} from "@/lib/viewer-resource"

export const DEFAULT_MAX_BYTES = 1_000_000
export const DEFAULT_MAX_LINES = 10_000
export const MAX_TEXT_RESOURCE_CACHE_ENTRIES = 64

export interface TextViewerBounds {
  maxBytes?: number
  maxLines?: number
}

export type TextViewerTooLargeReason = "bytes" | "lines"
export type TextViewerBoundName = "maxBytes" | "maxLines"

export class TextViewerTooLargeError extends ViewerFormatError {
  readonly reason: TextViewerTooLargeReason

  constructor(reason: TextViewerTooLargeReason) {
    super({
      format: "text",
      kind: "bounds",
      message: `Text file exceeds ${reason} limit`,
    })
    this.name = "TextViewerTooLargeError"
    this.reason = reason
  }
}

export class TextViewerInvalidBoundsError extends ViewerFormatError {
  readonly boundName: TextViewerBoundName

  constructor(boundName: TextViewerBoundName) {
    super({
      format: "text",
      kind: "bounds",
      message: `${boundName} must be a positive integer`,
    })
    this.name = "TextViewerInvalidBoundsError"
    this.boundName = boundName
  }
}

export function toTextFormatError(
  error: unknown,
  options: ViewerFormatErrorMapperOptions = {
    kind: "load_failed",
    message: "Failed to load text.",
  }
): ViewerFormatError {
  if (isViewerFormatError(error)) return error
  return new ViewerFormatError({
    format: "text",
    kind: options.kind,
    message: options.message,
    cause: error,
  })
}

interface TextResource {
  promise: Promise<string>
  status: "pending" | "resolved" | "rejected"
  value?: string
  error?: unknown
}

const textResourceCache = new Map<string, TextResource>()

export type TextViewerContent = ViewerContentIdentity &
  ViewerContentPayload &
  ViewerContentText

function textViewerResourceKey({
  content,
  retryVersion,
  bounds,
}: {
  content: ViewerContentIdentity
  retryVersion: number
  bounds: Required<TextViewerBounds>
}) {
  return `${content.key}\0${retryVersion}\0${bounds.maxBytes}\0${bounds.maxLines}`
}

export function clearTextViewerResourceCacheForTests() {
  textResourceCache.clear()
}

export function resolvedTextViewerBounds({
  maxBytes = DEFAULT_MAX_BYTES,
  maxLines = DEFAULT_MAX_LINES,
}: TextViewerBounds = {}): Required<TextViewerBounds> {
  return {
    maxBytes: resolveTextViewerBound(maxBytes, "maxBytes"),
    maxLines: resolveTextViewerBound(maxLines, "maxLines"),
  }
}

export function assertTextWithinBounds(
  text: string,
  bounds: Required<TextViewerBounds>
) {
  if (new TextEncoder().encode(text).byteLength > bounds.maxBytes) {
    throw new TextViewerTooLargeError("bytes")
  }
  if (lineCountOf(text) > bounds.maxLines) {
    throw new TextViewerTooLargeError("lines")
  }
}

// Split into stable source lines. The prose viewer may wrap each source line
// into several visual lines, but highlighting and scroll APIs stay source-line
// based.
export function splitTextLines(text: string) {
  return text.split(/\r\n|[\n\r\u2028\u2029]/g)
}

export function readTextResource({
  content,
  retryVersion,
  bounds,
}: {
  content: TextViewerContent
  retryVersion: number
  bounds: Required<TextViewerBounds>
}) {
  const inlineText = inlineTextResource(content)
  if (inlineText != null) {
    assertTextWithinBounds(inlineText, bounds)
    return inlineText
  }

  const resourceKey = textViewerResourceKey({ content, retryVersion, bounds })
  const textResource = getTextResource({ content, resourceKey, bounds })

  if (textResource.status === "resolved") return textResource.value ?? ""
  if (textResource.status === "rejected") throw textResource.error

  throw textResource.promise
}

function inlineTextResource(content: ViewerContentPayload) {
  return content.payload.kind === "text" ? content.payload.text : null
}

function getTextResource({
  content,
  resourceKey,
  bounds,
}: {
  content: TextViewerContent
  resourceKey: string
  bounds: Required<TextViewerBounds>
}) {
  let textResource = textResourceCache.get(resourceKey)
  if (!textResource) {
    const nextResource: TextResource = {
      status: "pending",
      promise: readBoundedTextResource(content, bounds),
    }
    nextResource.promise.then(
      (value) => {
        nextResource.status = "resolved"
        nextResource.value = value
      },
      (error) => {
        nextResource.status = "rejected"
        nextResource.error = error
      }
    )
    textResource = nextResource
    textResourceCache.set(resourceKey, textResource)
    trimTextResourceCache()
  }
  return textResource
}

async function readBoundedTextResource(
  content: ViewerContentText,
  bounds: Required<TextViewerBounds>
) {
  try {
    return await content.readText(bounds)
  } catch (error) {
    if (isResourceError(error)) throw error
    throw toTextFormatError(error)
  }
}

function lineCountOf(text: string) {
  return splitTextLines(text).length
}

function resolveTextViewerBound(value: number, boundName: TextViewerBoundName) {
  if (!Number.isSafeInteger(value) || value < 1) {
    throw new TextViewerInvalidBoundsError(boundName)
  }
  return value
}

function trimTextResourceCache() {
  while (textResourceCache.size > MAX_TEXT_RESOURCE_CACHE_ENTRIES) {
    const firstKey = textResourceCache.keys().next().value
    if (firstKey === undefined) return
    textResourceCache.delete(firstKey)
  }
}

import {
  createBlobDownloadAction,
  createHrefDownloadAction,
  createTextDownloadAction,
  type ViewerDownloadAction,
} from "@/lib/viewer-download"
import {
  isAbortError,
  ResourceError,
  type ResourceTooLargeReason,
} from "@/lib/viewer-errors"
import {
  resolveViewerDescriptor,
  type BlobViewerSource,
  type FileCategory,
  type TextSource,
  type UrlViewerSource,
  type ViewerDescriptor,
  type ViewerSource,
} from "@/lib/viewer-source"

export interface ResourceReadOptions {
  signal?: AbortSignal
}

export interface TextReadOptions extends ResourceReadOptions {
  maxBytes?: number
  maxLines?: number
}

export interface ByteRange {
  start: number
  end: number
}

export interface ByteRangeResult {
  buffer: ArrayBuffer
  contentRange?: {
    start: number
    end: number
    total: number | null
  }
  isComplete: boolean
}

export interface ViewerResourceKeys {
  readonly load: string
  readonly presentation: string
  readonly resource: string
}

export type ViewerResourcePayload =
  | { kind: "url"; url: string }
  | { kind: "blob"; blob: Blob }
  | { kind: "text"; text: string }

export interface ViewerResourceContent {
  readonly key: string
  readonly sourceKind: ViewerSource["kind"]
  readonly directUrl: string | null
  readonly mimeType?: string
  readonly payload: ViewerResourcePayload
  readBlob(options?: ResourceReadOptions): Promise<Blob>
  readBytes(options?: ResourceReadOptions): Promise<ArrayBuffer>
  readText(options?: TextReadOptions): Promise<string>
  readStream(options?: ResourceReadOptions): Promise<ReadableStream<Uint8Array>>
  readRange(
    range: ByteRange,
    options?: ResourceReadOptions
  ): Promise<ByteRangeResult>
}

export type ViewerContentIdentity = Pick<
  ViewerResourceContent,
  "key" | "sourceKind"
>

export type ViewerContentDirectUrl = ViewerContentIdentity &
  Pick<ViewerResourceContent, "directUrl">

export type ViewerContentPayload = ViewerContentIdentity &
  Pick<ViewerResourceContent, "payload">

export type ViewerContentMime = ViewerContentIdentity &
  Pick<ViewerResourceContent, "mimeType">

export type ViewerContentBlob = ViewerContentIdentity &
  Pick<ViewerResourceContent, "readBlob">

export type ViewerContentBytes = ViewerContentIdentity &
  Pick<ViewerResourceContent, "readBytes">

export type ViewerContentText = ViewerContentIdentity &
  Pick<ViewerResourceContent, "readText">

export type ViewerContentStream = ViewerContentIdentity &
  Pick<ViewerResourceContent, "readStream">

export type ViewerContentRange = ViewerContentIdentity &
  Pick<ViewerResourceContent, "readRange">

export interface ViewerResource {
  readonly descriptor: ViewerDescriptor
  readonly sourceKind: ViewerSource["kind"]
  readonly keys: ViewerResourceKeys
  readonly identityKey: string
  readonly fileName: string
  readonly mimeType?: string
  readonly content: ViewerResourceContent
  readonly originalDownload: ViewerDownloadAction
}

const URL_RESOURCE_REGISTRY_MAX = 128
const TEXT_RESOURCE_REGISTRY_MAX = 64
// LF, CR, CRLF, LINE SEPARATOR (U+2028), and PARAGRAPH SEPARATOR (U+2029) — the
// ECMAScript LineTerminator set, matching what a browser breaks on in a
// `white-space: pre` block. Kept in sync with text-viewer-resource's splitter.
const TEXT_LINE_BREAK_PATTERN = /\r\n|[\n\r\u2028\u2029]/g

const urlViewerResourceRegistry = new Map<string, ViewerResource>()
const urlViewerResourceContentRegistry = new Map<
  string,
  ViewerResourceContent
>()
const textViewerResourceRegistry = new Map<string, ViewerResource>()
const textViewerResourceContentRegistry = new Map<
  string,
  ViewerResourceContent
>()
let blobViewerResourceRegistry = new WeakMap<
  Blob,
  Map<string, ViewerResource>
>()
let blobViewerResourceContentRegistry = new WeakMap<
  Blob,
  Map<string, ViewerResourceContent>
>()
const blobObjectKeys = new WeakMap<Blob, string>()
let nextBlobObjectKey = 0

export function createViewerResource(
  source: ViewerSource,
  category?: FileCategory
): ViewerResource {
  const descriptor = resolveViewerDescriptor({ source, category })
  const keys = viewerResourceKeys(source, descriptor)

  if (source.kind === "url") {
    return internUrlResource(source, descriptor, keys)
  }
  if (source.kind === "blob") {
    return internBlobResource(source, descriptor, keys)
  }
  return internTextResource(source, descriptor, keys)
}

export function clearViewerResourceRegistryForTests() {
  urlViewerResourceRegistry.clear()
  urlViewerResourceContentRegistry.clear()
  textViewerResourceRegistry.clear()
  textViewerResourceContentRegistry.clear()
  blobViewerResourceRegistry = new WeakMap()
  blobViewerResourceContentRegistry = new WeakMap()
}

function internUrlResource(
  source: UrlViewerSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys
): ViewerResource {
  const cached = urlViewerResourceRegistry.get(keys.resource)
  if (cached) return cached

  const resource = createUrlResource(source, descriptor, keys)
  urlViewerResourceRegistry.set(keys.resource, resource)
  pruneUrlResourceRegistry()
  return resource
}

function internBlobResource(
  source: BlobViewerSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys
): ViewerResource {
  let resources = blobViewerResourceRegistry.get(source.blob)
  if (!resources) {
    resources = new Map()
    blobViewerResourceRegistry.set(source.blob, resources)
  }

  const cached = resources.get(keys.resource)
  if (cached) return cached

  const resource = createBlobResource(source, descriptor, keys)
  resources.set(keys.resource, resource)
  return resource
}

function internTextResource(
  source: TextSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys
): ViewerResource {
  const cached = textViewerResourceRegistry.get(keys.resource)
  if (cached) return cached

  const resource = createTextResource(source, descriptor, keys)
  textViewerResourceRegistry.set(keys.resource, resource)
  pruneTextResourceRegistry()
  return resource
}

function pruneUrlResourceRegistry() {
  while (urlViewerResourceRegistry.size > URL_RESOURCE_REGISTRY_MAX) {
    const firstKey = urlViewerResourceRegistry.keys().next().value
    if (!firstKey) return
    urlViewerResourceRegistry.delete(firstKey)
  }
}

function pruneUrlResourceContentRegistry() {
  while (urlViewerResourceContentRegistry.size > URL_RESOURCE_REGISTRY_MAX) {
    const firstKey = urlViewerResourceContentRegistry.keys().next().value
    if (!firstKey) return
    urlViewerResourceContentRegistry.delete(firstKey)
  }
}

function pruneTextResourceRegistry() {
  while (textViewerResourceRegistry.size > TEXT_RESOURCE_REGISTRY_MAX) {
    const firstKey = textViewerResourceRegistry.keys().next().value
    if (!firstKey) return
    textViewerResourceRegistry.delete(firstKey)
  }
}

function pruneTextResourceContentRegistry() {
  while (textViewerResourceContentRegistry.size > TEXT_RESOURCE_REGISTRY_MAX) {
    const firstKey = textViewerResourceContentRegistry.keys().next().value
    if (!firstKey) return
    textViewerResourceContentRegistry.delete(firstKey)
  }
}

function viewerResourceKeys(
  source: ViewerSource,
  descriptor: ViewerDescriptor
): ViewerResourceKeys {
  const load = viewerResourceLoadKey(source)
  const presentation = viewerResourcePresentationKey(source, descriptor)
  return {
    load,
    presentation,
    resource: [load, presentation].join("\u0000"),
  }
}

function viewerResourceLoadKey(source: ViewerSource) {
  return [
    source.kind,
    source.identityKey ?? "",
    sourceMimeType(source) ?? "",
    directLoadCacheKey(source),
    payloadCacheKey(source),
  ].join("\u0000")
}

function viewerResourcePresentationKey(
  source: ViewerSource,
  descriptor: ViewerDescriptor
) {
  return [
    descriptor.category,
    descriptor.displayName,
    descriptor.fileName,
    descriptor.mimeType ?? "",
    downloadCacheKey(source),
  ].join("\u0000")
}

function directLoadCacheKey(source: ViewerSource) {
  return source.kind === "url" ? source.url : ""
}

function downloadCacheKey(source: ViewerSource) {
  if (source.kind === "text") return ""
  return source.downloadUrl ?? ""
}

function payloadCacheKey(source: ViewerSource) {
  if (source.kind === "url") return ""
  if (source.kind === "blob") return blobObjectKey(source.blob)
  return `text:${source.text.length}:${hashString(source.text)}`
}

function sourceMimeType(source: ViewerSource) {
  if (source.kind === "blob") return source.mimeType ?? source.blob.type
  return source.mimeType
}

function blobObjectKey(blob: Blob) {
  let key = blobObjectKeys.get(blob)
  if (!key) {
    nextBlobObjectKey += 1
    key = `blob-object:${nextBlobObjectKey}`
    blobObjectKeys.set(blob, key)
  }
  return key
}

function hashString(text: string) {
  let hash = 0x811c9dc5
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index)
    hash = Math.imul(hash, 0x01000193)
  }
  return (hash >>> 0).toString(36)
}

export function blobSource(
  bytes: Blob | ArrayBuffer | Uint8Array,
  metadata: {
    identityKey: string
    fileName?: string
    mimeType?: string
    downloadUrl?: string
  }
): BlobViewerSource {
  const blob =
    bytes instanceof Blob
      ? bytes
      : new Blob(
          [bytes instanceof ArrayBuffer ? bytes : new Uint8Array(bytes)],
          {
            type: metadata.mimeType ?? "",
          }
        )
  return {
    kind: "blob",
    blob,
    fileName: metadata.fileName,
    mimeType: metadata.mimeType ?? blob.type,
    downloadUrl: metadata.downloadUrl,
    identityKey: metadata.identityKey,
  }
}

function createUrlResource(
  source: UrlViewerSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys
): ViewerResource {
  const content = internUrlResourceContent(source, keys)
  const originalDownload = createHrefDownloadAction({
    id: "download-original",
    label: "Download",
    href: source.downloadUrl ?? source.url,
    fileName: descriptor.fileName,
  })

  return resourceBase(source, descriptor, keys, { content, originalDownload })
}

function internUrlResourceContent(
  source: UrlViewerSource,
  keys: ViewerResourceKeys
): ViewerResourceContent {
  const cached = urlViewerResourceContentRegistry.get(keys.load)
  if (cached) return cached

  const content = resourceContentBase(source, keys, {
    directUrl: source.url,
    payload: { kind: "url", url: source.url },
    readBlob: async ({ signal } = {}) => {
      const response = await fetchResource(source.url, { signal })
      validateFullContentResponse(response)
      return readResponseBlob(response)
    },
    readBytes: async ({ signal } = {}) => {
      const response = await fetchResource(source.url, { signal })
      validateFullContentResponse(response)
      return readResponseArrayBuffer(response)
    },
    readText: async ({ signal, maxBytes, maxLines } = {}) => {
      const response = await fetchResource(source.url, { signal })
      return readBoundedResponseText(response, { maxBytes, maxLines })
    },
    readStream: async ({ signal } = {}) => {
      const response = await fetchResource(source.url, { signal })
      validateFullContentResponse(response)
      if (!response.body) {
        if (response.status === 204 || response.status === 205) {
          return emptyByteStream()
        }
        throw new ResourceError({
          kind: "unsupported_capability",
          message: "This response cannot be streamed.",
        })
      }
      return response.body
    },
    readRange: async (range, { signal } = {}) => {
      validateByteRange(range)
      const { start, end } = range
      const response = await fetchResource(source.url, {
        signal,
        headers: { Range: `bytes=${start}-${end}` },
      })
      const buffer = await readResponseArrayBuffer(response)
      const contentRange = parseContentRange(
        response.headers.get("content-range")
      )
      validateUrlRangeResponse({
        bufferLength: buffer.byteLength,
        contentRange,
        range,
        status: response.status,
      })
      return {
        buffer,
        contentRange,
        isComplete: isByteRangeComplete({
          bufferLength: buffer.byteLength,
          contentRange,
          requestedLength: end - start + 1,
          status: response.status,
        }),
      }
    },
  })
  urlViewerResourceContentRegistry.set(keys.load, content)
  pruneUrlResourceContentRegistry()
  return content
}

function emptyByteStream() {
  return new ReadableStream<Uint8Array>({
    start(controller) {
      controller.close()
    },
  })
}

function createBlobResource(
  source: BlobViewerSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys
): ViewerResource {
  const blob = source.blob
  const content = internBlobResourceContent(source, keys)
  const originalDownload = source.downloadUrl
    ? createHrefDownloadAction({
        id: "download-original",
        label: "Download",
        href: source.downloadUrl,
        fileName: descriptor.fileName,
      })
    : createBlobDownloadAction({
        id: "download-original",
        label: "Download",
        blob,
        fileName: descriptor.fileName,
      })

  return resourceBase(source, descriptor, keys, { content, originalDownload })
}

function internBlobResourceContent(
  source: BlobViewerSource,
  keys: ViewerResourceKeys
): ViewerResourceContent {
  const blob = source.blob
  let contents = blobViewerResourceContentRegistry.get(blob)
  if (!contents) {
    contents = new Map()
    blobViewerResourceContentRegistry.set(blob, contents)
  }

  const cached = contents.get(keys.load)
  if (cached) return cached

  const content = resourceContentBase(source, keys, {
    directUrl: null,
    payload: { kind: "blob", blob },
    readBlob: async () => blob,
    readBytes: async () => blob.arrayBuffer(),
    readText: async ({ maxBytes, maxLines } = {}) =>
      readBoundedBlobText(blob, { maxBytes, maxLines }),
    readStream: async () => blob.stream(),
    readRange: async (range) => {
      validateByteRange(range)
      const { start, end } = range
      validateKnownByteRangeStart(start, blob.size)
      const rangeBlob = blob.slice(start, end + 1)
      return {
        buffer: await rangeBlob.arrayBuffer(),
        contentRange: {
          start,
          end: Math.min(end, blob.size - 1),
          total: blob.size,
        },
        isComplete: end >= blob.size - 1,
      }
    },
  })
  contents.set(keys.load, content)
  return content
}

function createTextResource(
  source: TextSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys
): ViewerResource {
  const content = internTextResourceContent(source, keys)
  const originalDownload = createTextDownloadAction({
    id: "download-original",
    label: "Download",
    text: source.text,
    fileName: descriptor.fileName,
    mimeType: descriptor.mimeType,
  })

  return resourceBase(source, descriptor, keys, { content, originalDownload })
}

function internTextResourceContent(
  source: TextSource,
  keys: ViewerResourceKeys
): ViewerResourceContent {
  const cached = textViewerResourceContentRegistry.get(keys.load)
  if (cached) return cached

  const content = resourceContentBase(source, keys, {
    directUrl: null,
    payload: { kind: "text", text: source.text },
    readBlob: async () =>
      new Blob([source.text], {
        type: "text/plain;charset=utf-8",
      }),
    readBytes: async () =>
      typedArrayBuffer(new TextEncoder().encode(source.text)),
    readText: async ({ maxBytes, maxLines } = {}) =>
      readBoundedInlineText(source.text, { maxBytes, maxLines }),
    readStream: async () => new Blob([source.text]).stream(),
    readRange: async (range) => {
      validateByteRange(range)
      const { start, end } = range
      const buffer = new TextEncoder().encode(source.text)
      validateKnownByteRangeStart(start, buffer.byteLength)
      const slice = buffer.slice(start, end + 1)
      return {
        buffer: typedArrayBuffer(slice),
        contentRange: {
          start,
          end: Math.min(end, buffer.byteLength - 1),
          total: buffer.byteLength,
        },
        isComplete: end >= buffer.byteLength - 1,
      }
    },
  })
  textViewerResourceContentRegistry.set(keys.load, content)
  pruneTextResourceContentRegistry()
  return content
}

function resourceBase(
  source: ViewerSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys,
  options: {
    content: ViewerResourceContent
    originalDownload: ViewerDownloadAction
  }
): ViewerResource {
  const { content, originalDownload } = options
  return Object.freeze({
    descriptor,
    sourceKind: source.kind,
    keys,
    identityKey: descriptor.identityKey,
    fileName: descriptor.fileName,
    mimeType: descriptor.mimeType,
    content,
    originalDownload,
  })
}

function resourceContentBase(
  source: ViewerSource,
  keys: ViewerResourceKeys,
  methods: Omit<ViewerResourceContent, "key" | "sourceKind" | "mimeType">
): ViewerResourceContent {
  return Object.freeze({
    key: keys.load,
    sourceKind: source.kind,
    mimeType: sourceMimeType(source),
    ...methods,
  })
}

function typedArrayBuffer(bytes: Uint8Array): ArrayBuffer {
  return bytes.buffer.slice(
    bytes.byteOffset,
    bytes.byteOffset + bytes.byteLength
  ) as ArrayBuffer
}

async function fetchResource(
  input: RequestInfo | URL,
  init?: RequestInit
): Promise<Response> {
  let response: Response
  try {
    response = await fetch(input, init)
  } catch (error) {
    if (isAbortError(error)) {
      throw new ResourceError({
        kind: "aborted",
        message: "Loading was cancelled.",
        cause: error,
      })
    }
    throw new ResourceError({
      kind: "fetch_failed",
      message: "Could not fetch this resource.",
      cause: error,
    })
  }

  if (!response.ok && response.status !== 206) {
    throw new ResourceError({
      kind: "http_error",
      message: `Failed to load resource: ${response.status}`,
      status: response.status,
    })
  }

  return response
}

async function readBoundedResponseText(
  response: Response,
  bounds: { maxBytes?: number; maxLines?: number }
) {
  validateFullContentResponse(response)

  const maxBytes = bounds.maxBytes
  if (
    isContentLengthOverLimit(response.headers.get("content-length"), maxBytes)
  ) {
    throw tooLarge("bytes")
  }

  const body = response.body
  if (!body) {
    const buffer = await readResponseArrayBuffer(response)
    if (maxBytes != null && buffer.byteLength > maxBytes) {
      throw tooLarge("bytes")
    }
    const text = new TextDecoder().decode(buffer)
    assertLineLimit(text, bounds.maxLines)
    return text
  }

  const reader = body.getReader()
  const decoder = new TextDecoder()
  const lineLimitTracker = createLineLimitTracker(bounds.maxLines)
  let receivedBytes = 0
  let text = ""

  while (true) {
    const { done, value } = await readResponseStreamChunk(reader)
    if (done) break
    receivedBytes += value.byteLength
    if (maxBytes != null && receivedBytes > maxBytes) {
      await cancelReaderSilently(reader)
      throw tooLarge("bytes")
    }
    const chunkText = decoder.decode(value, { stream: true })
    try {
      lineLimitTracker.push(chunkText)
    } catch (error) {
      await cancelReaderSilently(reader)
      throw error
    }
    text += chunkText
  }

  const finalText = decoder.decode()
  lineLimitTracker.push(finalText)
  text += finalText
  assertLineLimit(text, bounds.maxLines)
  return text
}

function isContentLengthOverLimit(
  contentLength: string | null,
  maxBytes: number | undefined
) {
  if (maxBytes == null || contentLength == null) return false

  const normalizedLength = contentLength.trim().replace(/^0+(?=\d)/, "")
  if (!/^\d+$/.test(normalizedLength)) return false

  const maxLength = String(maxBytes)
  return (
    normalizedLength.length > maxLength.length ||
    (normalizedLength.length === maxLength.length &&
      normalizedLength > maxLength)
  )
}

function validateFullContentResponse(response: Response) {
  if (response.status !== 206) return

  const contentRange = parseContentRange(response.headers.get("content-range"))
  if (
    contentRange?.total != null &&
    contentRange.start === 0 &&
    contentRange.end === contentRange.total - 1
  ) {
    return
  }

  throw new ResourceError({
    kind: "partial_content",
    message: "Full response returned partial content.",
    status: response.status,
  })
}

async function readResponseStreamChunk(
  reader: ReadableStreamDefaultReader<Uint8Array>
) {
  try {
    return await reader.read()
  } catch (error) {
    throw resourceReadError(error)
  }
}

async function readResponseArrayBuffer(response: Response) {
  try {
    return await response.arrayBuffer()
  } catch (error) {
    throw resourceReadError(error)
  }
}

async function readResponseBlob(response: Response) {
  try {
    return await response.blob()
  } catch (error) {
    throw resourceReadError(error)
  }
}

function resourceReadError(error: unknown) {
  if (isAbortError(error)) {
    return new ResourceError({
      kind: "aborted",
      message: "Loading was cancelled.",
      cause: error,
    })
  }
  return new ResourceError({
    kind: "fetch_failed",
    message: "Could not read this resource.",
    cause: error,
  })
}

async function readBoundedBlobText(
  blob: Blob,
  bounds: { maxBytes?: number; maxLines?: number }
) {
  if (bounds.maxBytes != null && blob.size > bounds.maxBytes) {
    throw tooLarge("bytes")
  }
  const text = await blob.text()
  assertLineLimit(text, bounds.maxLines)
  return text
}

function readBoundedInlineText(
  text: string,
  { maxBytes, maxLines }: { maxBytes?: number; maxLines?: number }
) {
  // For inline sources the string *is* the resource, so its UTF-8 byte length
  // is the authoritative size to measure against maxBytes.
  if (
    maxBytes != null &&
    new TextEncoder().encode(text).byteLength > maxBytes
  ) {
    throw tooLarge("bytes")
  }
  assertLineLimit(text, maxLines)
  return text
}

// Used after a transferred-byte check has already enforced maxBytes (URL/blob).
// Re-encoding the decoded text here would double-count: invalid UTF-8 decodes to
// U+FFFD (3 bytes each), inflating the measured size past the real wire bytes
// and falsely rejecting small resources as "too large".
function assertLineLimit(text: string, maxLines: number | undefined) {
  if (
    maxLines != null &&
    text.split(TEXT_LINE_BREAK_PATTERN).length > maxLines
  ) {
    throw tooLarge("lines")
  }
}

function tooLarge(reason: ResourceTooLargeReason) {
  return new ResourceError({
    kind: "too_large",
    tooLargeReason: reason,
    message: `Resource exceeds ${reason} limit.`,
  })
}

async function cancelReaderSilently(
  reader: ReadableStreamDefaultReader<Uint8Array>
) {
  try {
    await reader.cancel()
  } catch {
    // Preserve the user-facing load failure; cancellation is best-effort cleanup.
  }
}

function validateByteRange({ start, end }: ByteRange) {
  if (
    !Number.isSafeInteger(start) ||
    !Number.isSafeInteger(end) ||
    start < 0 ||
    end < start
  ) {
    throw new ResourceError({
      kind: "invalid_range",
      message: "Byte range must use non-negative integer bounds.",
    })
  }
}

function validateKnownByteRangeStart(start: number, total: number) {
  if (start > 0 && start >= total) {
    throw new ResourceError({
      kind: "invalid_range",
      message: "Byte range starts past the available resource.",
    })
  }
}

function validateUrlRangeResponse({
  bufferLength,
  contentRange,
  range,
  status,
}: {
  bufferLength: number
  contentRange: ByteRangeResult["contentRange"]
  range: ByteRange
  status: number
}) {
  if (status === 200) {
    if (range.start !== 0 || bufferLength > range.end - range.start + 1) {
      throw new ResourceError({
        kind: "invalid_range",
        message: "Full response does not match the requested byte range.",
      })
    }
    return
  }
  if (status !== 206) {
    throw new ResourceError({
      kind: "invalid_range",
      message: "Range response must return full or partial content.",
    })
  }
  if (!contentRange) {
    throw new ResourceError({
      kind: "invalid_range",
      message: "Partial content response is missing a valid byte range.",
    })
  }
  const declaredLength = contentRange.end - contentRange.start + 1
  if (
    contentRange.start !== range.start ||
    contentRange.end < contentRange.start ||
    contentRange.end > range.end ||
    (contentRange.total != null && contentRange.end >= contentRange.total) ||
    declaredLength !== bufferLength
  ) {
    throw new ResourceError({
      kind: "invalid_range",
      message: "Response byte range does not match the requested range.",
    })
  }
}

function isByteRangeComplete({
  bufferLength,
  contentRange,
  requestedLength,
  status,
}: {
  bufferLength: number
  contentRange: ByteRangeResult["contentRange"]
  requestedLength: number
  status: number
}) {
  if (status === 200) return true
  if (contentRange?.total != null) {
    if (contentRange.total <= 0) return true
    return contentRange.end >= contentRange.total - 1
  }
  if (contentRange) return false
  return bufferLength < requestedLength
}

function isStandaloneLineBreak(character: string) {
  const code = character.charCodeAt(0)
  return code === 0x0a || code === 0x2028 || code === 0x2029
}

function createLineLimitTracker(maxLines: number | undefined) {
  let lineCount = 1
  let previousWasCR = false

  return {
    push(text: string) {
      if (maxLines == null || text.length === 0) return

      for (const character of text) {
        if (previousWasCR) {
          previousWasCR = false
          if (character === "\n") continue
        }

        if (character === "\r") {
          lineCount += 1
          previousWasCR = true
        } else if (isStandaloneLineBreak(character)) {
          // LF, plus LINE/PARAGRAPH SEPARATOR (U+2028/U+2029); none pair with CR.
          lineCount += 1
        }

        if (lineCount > maxLines) {
          throw tooLarge("lines")
        }
      }
    },
  }
}

function parseContentRange(value: string | null) {
  if (!value) return undefined
  const match = value.match(/^bytes\s+(\d+)-(\d+)\/(\d+|\*)\s*$/i)
  if (!match) return undefined
  const start = parseContentRangeNumber(match[1])
  const end = parseContentRangeNumber(match[2])
  const total =
    match[3] === "*" ? null : parseContentRangeNumber(match[3] ?? "")
  if (start == null || end == null || total === undefined) return undefined
  return {
    start,
    end,
    total,
  }
}

function parseContentRangeNumber(value: string) {
  const number = Number(value)
  return Number.isSafeInteger(number) ? number : undefined
}

export type ViewerDownloadOrigin = "original" | "derived"

export type ViewerDownloadPayload =
  | { kind: "href"; href: string }
  | { kind: "blob"; blob: Blob }
  | { kind: "text"; text: string; mimeType?: string }
  | { kind: "none" }

export interface ViewerDownloadAction {
  id: string
  label: string
  fileName: string
  origin: ViewerDownloadOrigin
  isDisabled?: boolean
  getPayload: (options?: {
    signal?: AbortSignal
  }) => ViewerDownloadPayload | Promise<ViewerDownloadPayload>
}

export type ViewerDownloadErrorKind =
  | "disabled"
  | "aborted"
  | "payload_failed"
  | "unsupported"

export class ViewerDownloadError extends Error {
  readonly kind: ViewerDownloadErrorKind
  readonly actionId: string
  override readonly cause?: unknown

  constructor({
    actionId,
    kind,
    message,
    cause,
  }: {
    actionId: string
    kind: ViewerDownloadErrorKind
    message: string
    cause?: unknown
  }) {
    super(message)
    this.name = "ViewerDownloadError"
    this.actionId = actionId
    this.kind = kind
    this.cause = cause
  }
}

export function createHrefDownloadAction({
  id,
  label = "Download",
  href,
  fileName,
  origin = "original",
}: {
  id: string
  label?: string
  href: string
  fileName: string
  origin?: ViewerDownloadOrigin
}): ViewerDownloadAction {
  return {
    id,
    label,
    fileName,
    origin,
    getPayload: () => ({ kind: "href", href }),
